 $local=Get-Date;$minute=$local.Hour*60+$local.Minute;$windowMinutes=if($NaturalWindowEnd){61}else{[Math]::Min(700,[Math]::Ceiling(($end-[DateTime]::UtcNow).TotalMinutes)+10)}
